package com.example.practice;

import org.jpos.iso.ISOException;
import org.jpos.iso.ISOMsg;

/**
 * The gateway's first look at a terminal's request. A request whose field 22 and card fields
 * contradict each other is answered here, with response code 30, and never goes upstream.
 */
public class EntryModeScreen {
    /** The PAN-entry codes in the acquirer's specification: the first two digits of field 22. */
    static final String KEYED = "01", STRIPE = "90", CHIP = "05", CONTACTLESS_CHIP = "07";

    /** The answer for the terminal when the request can't go upstream, or null when it can. */
    public ISOMsg screen(ISOMsg fromTerminal) throws ISOException {
        String problem = problem(fromTerminal);
        if (problem == null)
            return null;
        ISOMsg refusal = (ISOMsg) fromTerminal.clone(new int[] { 0, 3, 4, 11, 41, 42 });
        refusal.setResponseMTI();
        refusal.set(39, "30");
        return refusal;
    }

    /** Why field 22 and the card fields disagree, or null when they tell the same story. */
    String problem(ISOMsg m) {
        String entry = m.getString(22);
        if (entry == null || entry.length() != 3)
            return "no entry mode";
        switch (entry.substring(0, 2)) {
            case KEYED:
                return m.hasField(14) && !m.hasField(35) && !m.hasField(55) ? null : "keyed, but card fields disagree";
            case STRIPE:
                return m.hasField(35) && !m.hasField(55) ? null : "stripe read, but card fields disagree";
            case CHIP:
            case CONTACTLESS_CHIP:
                return m.hasField(35) && m.hasField(55) ? null : "chip read, but card fields disagree";
            default:
                return "entry mode " + entry + " is not in the specification";
        }
    }
}

import com.example.practice.EntryModeScreen;
import org.jpos.iso.ISOMsg;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        Logger root = Logger.getLogger("");
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            EntryModeScreen screen = new EntryModeScreen();
            System.out.println("contactless with chip data: " + verdict(screen.screen(purchase("071", true, true))));
            System.out.println("stripe, no PIN pad: " + verdict(screen.screen(purchase("902", true, false))));
            System.out.println("chip code, track only: " + verdict(screen.screen(purchase("051", true, false))));
            System.out.println("stripe code with chip data: " + verdict(screen.screen(purchase("901", true, true))));
            System.out.println("entry mode 81: " + verdict(screen.screen(purchase("811", true, false))));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    private static String verdict(ISOMsg answer) throws Exception {
        return answer == null ? "goes upstream" : answer.getMTI() + " response code " + answer.getString(39);
    }

    private static ISOMsg purchase(String entryMode, boolean track2, boolean icc) throws Exception {
        ISOMsg m = new ISOMsg("0200");
        m.set(2, "4761739001010010");
        m.set(3, "000000");
        m.set(4, "000000001275");
        m.set(11, "009904");
        m.set(22, entryMode);
        m.set(41, "40220077");
        if (track2) m.set(35, "4761739001010010=28122011143804400000");
        if (icc) m.set(55, new byte[] { (byte) 0x9F, 0x26, 0x02, 0x0A, 0x0B });
        return m;
    }
}

